{
  "findings": [
    {
      "check_id": "CKV_AWS_356",
      "title": "IAM policy allows actions on all resources (wildcard)",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "HIGH",
      "explanation": "The IAM policy grants 'ssm:StartSession' and related EC2/SSM permissions on Resource = "*". This violates the principle of least privilege, allowing any principal with this policy to start sessions on any EC2 instance in the account, significantly increasing the blast radius of a compromised credential."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
           "ssm:DescribeSessions",
            "ssm:GetConnectionStatus",
            "ssm:DescribeInstanceProperties",
            "ssm:TerminateSession",
            "ssm:ResumeSession"
        ]
        # TODO: Replace wildcard with specific ARNs or use conditions to restrict access
        Resource = "*"
      },
    ]
  })
}",
  "fix_summary": "Added a TODO comment highlighting the need to replace the wildcard resource with specific ARNs or conditions, as automated remediation cannot determine the correct target instances without additional context."
}
